#!/usr/bin/env python3
import sys
import json
import argparse
from pd.runtime import API

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--state",
        type=str,
        required=True
    )
    args = parser.parse_args()

    with open(args.state, "r") as f:
        zero_ref = json.load(f)

    api = API("/dev/puddleduck_ctrl")
    api.updateJointZeroRef(zero_ref);